questions.question:
What is the output of the following C code?
#include <stdio.h>
int main() {
    int a[] = {10, 20, 30, 40};
    int *p = a;
    printf("%d, %d", *p++, (*p)++);
    return 0;
}

What is the output of the following C code?
#include <stdio.h>
int main() {
    int x = 5;
    if (x == 5)
        printf("Yes ");
    else
        printf("No ");
    printf("End");
    return 0;
}
